// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 burnAmount, address caller, address otherUser, uint256 otherBalance) public {
        vm.assume(caller != address(0));
        vm.assume(otherUser != address(0));
        vm.assume(caller != otherUser);
        vm.assume(burnAmount <= type(uint256).max - 1);
        vm.assume(otherBalance <= type(uint256).max - 1);

        // Transfer some tokens to otherUser so its balance is known
        uint256 transferAmount = otherBalance > 1e18 ? 1e18 : otherBalance;
        vm.prank(c.owner());
        c.mintToken(otherUser, transferAmount);

        // Record state before burn
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 callerBalanceBefore = c.balanceOf(caller);
        uint256 otherBalanceBefore = c.balanceOf(otherUser);

        // Perform burn as caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));

        // After burn: totalSupply - sum(balanceOf) should be >= 0
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 callerBalanceAfter = c.balanceOf(caller);
        uint256 otherBalanceAfter = c.balanceOf(otherUser);

        uint256 sumBalances = callerBalanceAfter + otherBalanceAfter;

        // For owner: they may have initial supply, but we haven't tracked it perfectly
        // Use a simpler invariant: totalSupply - totalBalanceOfAllAccounts is preserved
        // Since we can't enumerate all accounts, we check a key invariant:
        // For the caller, if burn succeeded or failed, the difference totalSupply - sum(balances) should be >= 0
        require(totalSupplyAfter >= sumBalances, "Invariant violated: debt");

        assertTrue(true);
    }
}

